export const LINES = [{"id": "L01", "t0": 0.4, "t1": 5.8, "text": "Pernah gak, kamu disuruh beli Aqua, padahal yang dibeli justru air mineral merek lain?"}, {"id": "L02", "t0": 6.44, "t1": 9.48, "text": "Misalnya, Le Minerale, Club, atau Cleo."}, {"id": "L03", "t0": 10.08, "t1": 13.94, "text": "Tapi anehnya, orang yang menyuruhmu mungkin tetap menyebutnya Aqua."}, {"id": "L04", "t0": 14.64, "t1": 16.96, "text": "Nah, kenapa kebiasaan ini bisa terjadi?"}, {"id": "L05", "t0": 17.64, "t1": 19.4, "text": "Jawabannya ternyata menarik."}, {"id": "L06", "t0": 19.88, "t1": 23.14, "text": "Aqua sebenarnya bukan nama untuk semua air mineral."}, {"id": "L07", "t0": 23.5, "t1": 28.24, "text": "Aqua adalah nama sebuah merek air minum dalam kemasan asal Indonesia."}, {"id": "L08", "t0": 29.04, "t1": 32.18, "text": "Nama ini berasal dari bahasa Latin yang berarti air."}, {"id": "L09", "t0": 32.9, "t1": 38.26, "text": "Namun, perjalanan merek ini ternyata sudah dimulai sejak lebih dari lima dekade lalu."}, {"id": "L10", "t0": 38.82, "t1": 41.76, "text": "Ceritanya bermula pada tahun 1973."}, {"id": "L11", "t0": 43.14, "t1": 48.02, "text": "Saat itu, air minum dalam kemasan belum menjadi sesuatu yang umum seperti sekarang."}, {"id": "L12", "t0": 48.74, "t1": 53.68, "text": "Kebanyakan masyarakat masih terbiasa merebus air sendiri untuk kebutuhan minum sehari-hari."}, {"id": "L13", "t0": 54.16, "t1": 60.86, "text": "Di tengah kebiasaan tersebut, muncul sebuah gagasan untuk menyediakan air minum siap konsumsi dalam kemasan."}, {"id": "L14", "t0": 61.24, "t1": 64.4, "text": "Sosok di balik lahirnya Aqua adalah Tirto Utomo."}, {"id": "L15", "t0": 65.12, "t1": 72.38, "text": "Pada 23 Februari 1973, ia mendirikan perusahaan bernama PT Golden Mississippi."}, {"id": "L16", "t0": 72.8, "t1": 77.96, "text": "Ia melihat peluang untuk menghadirkan air minum yang praktis dan higienis bagi masyarakat."}, {"id": "L17", "t0": 78.44, "t1": 82.0, "text": "Dari gagasan inilah, perjalanan Aqua di Indonesia dimulai."}, {"id": "L18", "t0": 82.56, "t1": 89.6, "text": "Setahun setelah perusahaan didirikan, tepatnya pada tahun 1974, Aqua mulai dipasarkan."}, {"id": "L19", "t0": 90.3, "t1": 98.24, "text": "Produk pertamanya menggunakan botol kaca berukuran 950 ml, dengan harga sekitar Rp75 per botol."}, {"id": "L20", "t0": 98.8, "t1": 103.62, "text": "Pada masa itu, menjual air putih dalam kemasan bukanlah bisnis yang mudah."}, {"id": "L21", "t0": 103.64, "t1": 109.38, "text": "Sebab, masyarakat belum terbiasa membeli sesuatu yang biasanya bisa mereka dapatkan sendiri di rumah."}, {"id": "L22", "t0": 109.94, "t1": 115.4, "text": "Seiring berjalannya waktu, kebutuhan masyarakat terhadap air minum yang praktis semakin berkembang."}, {"id": "L23", "t0": 115.7, "t1": 120.06, "text": "Aqua terus memperluas distribusi dan membangun kepercayaan konsumen."}, {"id": "L24", "t0": 120.68, "t1": 126.52, "text": "Produknya semakin mudah ditemukan, mulai dari toko, warung, hingga pusat perbelanjaan."}, {"id": "L25", "t0": 127.08, "t1": 133.12, "text": "Kehadirannya yang lebih dahulu dikenal, membuat nama Aqua semakin kuat melekat dalam ingatan masyarakat Indonesia."}, {"id": "L26", "t0": 133.12, "t1": 139.74, "text": "Karena sudah lebih dahulu dikenal luas, nama Aqua akhirnya begitu melekat dalam kebiasaan masyarakat."}, {"id": "L27", "t0": 140.14, "t1": 147.84, "text": "Bahkan, ketika merek-merek lain bermunculan, sebagian orang tetap menggunakan kata Aqua untuk menyebut air mineral dalam kemasan."}, {"id": "L28", "t0": 148.38, "t1": 156.0, "text": "Fenomena ini disebut genericized trademark, yaitu ketika nama merek digunakan secara umum untuk menyebut produk sejenis."}, {"id": "L29", "t0": 156.46, "t1": 158.74, "text": "Jadi, sekarang kamu tahu asal-usulnya!"}, {"id": "L30", "t0": 158.74, "t1": 166.5, "text": "Nah, kalau di daerahmu, semua air mineral juga disebut Aqua? Tulis di kolom komentar, dan jangan lupa share video ini!"}];
